build.unitScript:
test("8 units at 5.00 gives 2 free, 6 paid and a 27.00 line total (AC-1)", () => {
  assert.deepEqual(code.priceLine({ sku: "A1", units: 8, unitPrice: 5 }), { sku: "A1", normalPrice: 40, freeUnits: 2, paidUnits: 6, lineTotal: 27 });
});
test("3 units at 5.00 get no free unit and only the 10% discount, 13.50 (AC-2)", () => {
  const r = code.priceLine({ sku: "A1", units: 3, unitPrice: 5 });
  assert.equal(r.freeUnits, 0);
  assert.equal(r.paidUnits, 3);
  assert.equal(r.normalPrice, 15);
  assert.equal(r.lineTotal, 13.5);
});
test("7 units at 5.00 give 1 free unit, the leftover units are charged, 27.00 (AC-3)", () => {
  const r = code.priceLine({ sku: "A1", units: 7, unitPrice: 5 });
  assert.equal(r.freeUnits, 1);
  assert.equal(r.paidUnits, 6);
  assert.equal(r.lineTotal, 27);
});
test("0 units gives a 0.00 total and -1 units is rejected with an error (AC-4)", () => {
  const r = code.priceLine({ sku: "A1", units: 0, unitPrice: 5 });
  assert.equal(r.lineTotal, 0);
  assert.equal(r.freeUnits, 0);
  assert.throws(() => code.priceLine({ sku: "A1", units: -1, unitPrice: 5 }), /^invalid field: units$/);
});
test("half-cent results round up once at the end: 1 at 0.05 gives 0.05 and 3 at 0.15 gives 0.41 (AC-5)", () => {
  assert.equal(code.priceLine({ sku: "B2", units: 1, unitPrice: 0.05 }).lineTotal, 0.05);
  assert.equal(code.priceLine({ sku: "B2", units: 3, unitPrice: 0.15 }).lineTotal, 0.41);
});
test("a negative unit price or fractional units are rejected and name the field", () => {
  assert.throws(() => code.priceLine({ sku: "A1", units: 2, unitPrice: -0.01 }), /^invalid field: unitPrice$/);
  assert.throws(() => code.priceLine({ sku: "A1", units: 2.5, unitPrice: 5 }), /^invalid field: units$/);
});

build.testScript:
test("both offers apply and the 10 percent discount is only on paid units", function() {
  assert.deepEqual(code.priceLine({ sku: "SKU", units: 8, unitPrice: 5 }), {
    sku: "SKU",
    normalPrice: 40,
    freeUnits: 2,
    paidUnits: 6,
    lineTotal: 27
  });
});
test("units under 4 get only the 10 percent discount", function() {
  assert.deepEqual(code.priceLine({ sku: "SKU", units: 3, unitPrice: 5 }), {
    sku: "SKU",
    normalPrice: 15,
    freeUnits: 0,
    paidUnits: 3,
    lineTotal: 13.5
  });
});
test("free units are the floor of units divided by 4 and leftover units are charged", function() {
  assert.deepEqual(code.priceLine({ sku: "SKU", units: 7, unitPrice: 5 }), {
    sku: "SKU",
    normalPrice: 35,
    freeUnits: 1,
    paidUnits: 6,
    lineTotal: 27
  });
});
test("one free unit is waived in each complete set of four", function() {
  assert.deepEqual(code.priceLine({ sku: "SKU", units: 4, unitPrice: 5 }), {
    sku: "SKU",
    normalPrice: 20,
    freeUnits: 1,
    paidUnits: 3,
    lineTotal: 13.5
  });
});
test("zero units is valid and the line total is zero", function() {
  assert.deepEqual(code.priceLine({ sku: "SKU", units: 0, unitPrice: 5 }), {
    sku: "SKU",
    normalPrice: 0,
    freeUnits: 0,
    paidUnits: 0,
    lineTotal: 0
  });
});
test("negative units are rejected with an error and no total is returned", function() {
  assert.throws(function() {
    code.priceLine({ sku: "SKU", units: -1, unitPrice: 5 });
  }, /^invalid field: units$/);
});
test("a negative unit price is rejected with an error and no total is returned", function() {
  assert.throws(function() {
    code.priceLine({ sku: "SKU", units: 1, unitPrice: -1 });
  }, /^invalid field: unitPrice$/);
});
test("the line total is rounded once at the end half up to 2 decimals", function() {
  assert.deepEqual(code.priceLine({ sku: "SKU", units: 1, unitPrice: 0.05 }), {
    sku: "SKU",
    normalPrice: 0.05,
    freeUnits: 0,
    paidUnits: 1,
    lineTotal: 0.05
  });
});

